  ('courchevel-france', '01F', 'Courchevel', 'France', 'The crown jewel of the world''s largest ski area', 'live', 'verified', 'northernLights', 'French Alps', '{"ski","ultra","culinary","romance","wellness","family"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'core', '{"key_facts":["Crown jewel of Les 3 Vallées — world''s largest linked ski area: 600 km of piste + 50 km ski routes, 159 lifts, 1,100-3,230 m span","Four altitude villages named for their metres: Le Praz (1300), Courchevel Village (1550), Moriond (1650), Courchevel 1850; La Saulire summit 2,738 m","85% of ski area above 1,800 m + 2,100+ snow cannons; 6-day 3 Vallees pass EUR 409 (2025/26)","Courchevel Altiport at 2,008 m — world''s first mountain airfield (opened 1961/62), 537 m runway at 18.6% gradient, no go-around","Most Michelin-starred ski resort on earth: 7 starred restaurants, 13 stars; Le 1947 a Cheval Blanc holds 3 stars","Five Palace-distinction hotels (Atout France label, 2010; 31 in France): Cheval Blanc, Les Airelles, L''Apogee, Le K2 Palace, Barriere Les Neiges","France''s first purpose-built ski resort (founded 1946); 80th anniversary in 2026; Emile Allais + first Sno-Cat grooming 1959","Aquamotion 10,500 m2 — largest aquatic centre in the French Alps, only in-resort indoor surf wave in Europe","Men''s Alpine Ski World Cup 13-15 Mar 2026 on L''Eclipse; confirmed 2030 French-Alps Olympics speed venue + ski jumping at Le Praz","International Pyrotechnic Art Festival (Feb-early Mar); Moriond Racing 3 km toboggan run through 8 tunnels"],"safety":{"emergency":"112 (Europe) / 15 SAMU / 17 police / 18 fire / 114 SMS; mountain rescue via 112 / PGHM","hospital":"Resort clinics; hospitals Moutiers / Bourg-Saint-Maurice / Albertville; trauma Chambery / Grenoble / Annecy; heli evac SMUR/PGHM","advisory_level":"L2","malaria":"none","yellow_fever":"not required","activity_note":"High-alpine winter sports: off-piste avalanche risk (Meteo-France BERA, 5-level scale, Haute-Tarentaise; transceiver/shovel/probe + guide), cold/altitude to 3,230 m, altiport visual-only weather-gated; rescue 112/PGHM","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/france","read":"2026-08-19","page_updated":"2026-08-11T10:17:02+01:00"}},"timing":{"peak":"High winter — Christmas/New Year, Feb half-terms + Easter; palace multiples + min-stay","shoulder":"Early Dec (season opening) + mid-Mar-Apr spring skiing","green":"May-Nov green season (most lifts/palaces closed; small summer hiking/altiport offer)","booking_lead":"Christmas/NY + Feb + Easter + top Palaces/chalets 6-12 mo; regular winter 2-4 mo; spring-ski 1-3 mo","off_season_specials":"Spring-ski value weeks (mid-Mar-Apr); small summer season (hiking, Aquamotion, altiport flights, golf)","event_peaks":"Christmas/NY, Feb half-terms + Pyrotechnic Art Festival (Feb-early Mar), Easter, Alpine Ski World Cup (mid-Mar)","campaign_start":"Next winter + Palaces/chalets from prior spring/summer (6-12 mo); spring-ski from Jan; 80th-anniversary + 2030-Olympics story all season"},"jewels":[{"name":"Ski the whole Trois Vallees — 600 km on one pass","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"6-day pass ~EUR 409; private instructor ~EUR 400-700/day (approx)","timing":"ski ~early Dec-mid-Apr; verify","draw_rank":1,"hook":"from Courchevel''s doorstep, link Courchevel + Méribel + the Belleville valley across the biggest connected ski area on earth","si":"ski","blurb":"from Courchevel''s doorstep, link Courchevel + Méribel + the Belleville valley across the biggest connected ski area on earth","when":"ski ~early Dec-mid-Apr; verify","commission":"school/operator 10-15%"},{"name":"The Saulire summit + crossover to Meribel","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"within pass (approx)","timing":"High winter — Christmas/New Year, Feb half-terms + Easter","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"